package com.bank.spark.model;

import java.math.BigDecimal;

// A single banking transaction. Normal top-level class, not static inner.
public class Transaction {
    private final String txnId;
    private final String accountId;   // the partition key for hash variants
    private final BigDecimal amount;

    public Transaction(String txnId, String accountId, BigDecimal amount) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
    }

    public String getTxnId() { return txnId; }
    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
}
