package com.bank.spark.partition;

import com.bank.spark.model.Transaction;

// Mimics repartition(n): deal records like cards into n partitions.
public class RoundRobinPartitioner {
    private final int numPartitions;

    public RoundRobinPartitioner(int numPartitions) {
        this.numPartitions = numPartitions;
    }

    // Partition index is just the running counter modulo n — pure balance.
    public int partitionFor(int recordIndex) {
        return recordIndex % numPartitions;
    }

    public int getNumPartitions() { return numPartitions; }
}
