package com.bank.spark.partition;

// Mimics repartition(cols) and repartition(n, cols): hash-modulo on the key.
public class HashKeyPartitioner {
    private final int numPartitions;

    public HashKeyPartitioner(int numPartitions) {
        this.numPartitions = numPartitions;
    }

    // Spark uses a non-negative hash modulo partition count.
    public int partitionFor(String key) {
        return Math.floorMod(key.hashCode(), numPartitions);
    }

    public int getNumPartitions() { return numPartitions; }
}
