package com.bank.spark.service;

// Decides which repartition variant fits the goal. Single Responsibility.
public class PartitionPlanner {

    public enum Goal { EVEN_BALANCE, KEY_COLOCATION, KEY_COLOCATION_FIXED_COUNT }

    // Returns a human-readable recommendation for the given goal.
    public String recommend(Goal goal) {
        switch (goal) {
            case EVEN_BALANCE:
                return "repartition(n) — round-robin, perfectly even, ignores keys";
            case KEY_COLOCATION:
                return "repartition(col) — hash on key, default 200 partitions";
            case KEY_COLOCATION_FIXED_COUNT:
                return "repartition(n, col) — hash on key into exactly n partitions";
            default:
                throw new IllegalArgumentException("Unknown goal: " + goal);
        }
    }
}
