package com.bank.spark;

import com.bank.spark.model.Transaction;
import com.bank.spark.partition.HashKeyPartitioner;
import com.bank.spark.partition.RoundRobinPartitioner;
import com.bank.spark.service.PartitionPlanner;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RepartitionDemo {

    private static final Logger log = Logger.getLogger(RepartitionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build the day's transactions for Rajesh and Priya.
        List<Transaction> txns = new ArrayList<>();
        txns.add(new Transaction("T1", "SAV2001", new BigDecimal("50000")));
        txns.add(new Transaction("T2", "SAV2001", new BigDecimal("75000")));
        txns.add(new Transaction("T3", "CUR3001", new BigDecimal("20000")));
        txns.add(new Transaction("T4", "SAV2001", new BigDecimal("12000")));
        txns.add(new Transaction("T5", "CUR3001", new BigDecimal("90000")));
        txns.add(new Transaction("T6", "CUR3001", new BigDecimal("30000")));

        PartitionPlanner planner = new PartitionPlanner();

        // Variant 1: repartition(n) — even round-robin into 3 partitions.
        log.info(() -> "Goal EVEN_BALANCE -> " + planner.recommend(PartitionPlanner.Goal.EVEN_BALANCE));
        RoundRobinPartitioner rr = new RoundRobinPartitioner(3);
        for (int i = 0; i < txns.size(); i++) {
            Transaction t = txns.get(i);
            int p = rr.partitionFor(i);
            log.info("repartition(3): " + t.getTxnId() + " acct=" + t.getAccountId() + " -> partition " + p);
        }

        // Variant 2: repartition(col) — hash on account, default count (use 200, show modulo into 4 for brevity).
        log.info(() -> "Goal KEY_COLOCATION -> " + planner.recommend(PartitionPlanner.Goal.KEY_COLOCATION));
        HashKeyPartitioner hashDefault = new HashKeyPartitioner(4); // stands in for 200
        for (Transaction t : txns) {
            int p = hashDefault.partitionFor(t.getAccountId());
            log.info("repartition(accountId): " + t.getTxnId() + " acct=" + t.getAccountId() + " -> partition " + p);
        }

        // Variant 3: repartition(n, col) — hash on account into exactly 2 partitions.
        log.info(() -> "Goal KEY_COLOCATION_FIXED_COUNT -> " + planner.recommend(PartitionPlanner.Goal.KEY_COLOCATION_FIXED_COUNT));
        HashKeyPartitioner hashFixed = new HashKeyPartitioner(2);
        for (Transaction t : txns) {
            int p = hashFixed.partitionFor(t.getAccountId());
            log.info("repartition(2, accountId): " + t.getTxnId() + " acct=" + t.getAccountId() + " -> partition " + p);
        }

        log.info("Demo complete: round-robin spreads evenly; hash keeps each account together.");
    }
}

